#include <sys/socket.h>
#include <unistd.h>
#include <fcntl.h>
#include <stdio.h>
#include <string.h>
static int count(void) { int n=0; for(int i=0;i<4096;i++) n += fcntl(i,F_GETFD)!=-1; return n; }
int main(void) {
 int pair[2]; socketpair(AF_UNIX,SOCK_STREAM,0,pair);
 char ctl[CMSG_SPACE(254*sizeof(int))]; memset(ctl,0,sizeof ctl);
 struct iovec iov={.iov_base="Z",.iov_len=0};
 struct msghdr m={.msg_iov=&iov,.msg_iovlen=1,.msg_control=ctl,.msg_controllen=sizeof ctl};
 struct cmsghdr *h=CMSG_FIRSTHDR(&m); h->cmsg_level=SOL_SOCKET; h->cmsg_type=SCM_RIGHTS; h->cmsg_len=CMSG_LEN(254*sizeof(int));
 int *fds=(int*)CMSG_DATA(h); for(int i=0;i<254;i++) fds[i]=pair[0];
 for(int i=0;i<4;i++) printf("send=%zd\n",sendmsg(pair[0],&m,0));
 write(pair[0],"Z",1); int before=count(); char data[8],in[2048]; iov=(struct iovec){data,sizeof data}; m=(struct msghdr){.msg_iov=&iov,.msg_iovlen=1,.msg_control=in,.msg_controllen=sizeof in};
 ssize_t rc=recvmsg(pair[1],&m,0); printf("recv=%zd control=%u ctrunc=%d installed=%d\n",rc,(unsigned)m.msg_controllen,!!(m.msg_flags&MSG_CTRUNC),count()-before);
}
